// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0x1));
        amount = bound(amount, 1, 1e30);

        uint256 before = c.getBalance(actor);
        vm.assume(before + amount >= before);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // General rule: addToBalance credits exactly msg.value to the CALLER's entry.
        assertTrue(c.getBalance(actor) == before + amount);
    }
}
